// HasSite applies the HasEdge predicate on the "site" edge.
func HasSite() predicate.IQCheckResult {
	return predicate.IQCheckResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SiteTable, SiteColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSiteWith applies the HasEdge predicate on the "site" edge with a given conditions (other predicates).
func HasSiteWith(preds ...predicate.IQCheckSite) predicate.IQCheckResult {
	return predicate.IQCheckResult(func(s *sql.Selector) {
		step := newSiteStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IQCheckResult) predicate.IQCheckResult {
	return predicate.IQCheckResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IQCheckResult) predicate.IQCheckResult {
	return predicate.IQCheckResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IQCheckResult) predicate.IQCheckResult {
	return predicate.IQCheckResult(sql.NotPredicates(p))
}
